CREATE TABLE sessions(session_id BIGSERIAL PRIMARY KEY,user_id INT REFERENCES users(user_id),device_id INT REFERENCES devices(device_id),login_time TIMESTAMP,logout_time TIMESTAMP,session_duration_seconds INT,network_type VARCHAR(20),city VARCHAR(100),app_version VARCHAR(20),crash_flag BOOLEAN DEFAULT FALSE,crash_reason VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);